using System;
using Framework.Parameters;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// ParameterModifierの基本機能と境界条件を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class ParameterModifierTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行し、結果を集計する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestAdditive();
                TestMultiplicative();
                TestIdentifier();
                TestSource();
                TestNeutral();
                TestInvalidInput();
                TestToString();
            }
            catch (Exception exception)
            {
                failedCount++;
                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【ParameterModifier テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗したテストを確認してください。"),
                this);
        }

        /// <summary>
        /// 加算補正の生成と保持情報を検証する。
        /// </summary>
        private void TestAdditive()
        {
            var modifier =
                ParameterModifier.CreateAdditive(2f);

            bool typePassed =
                modifier.Type == ParameterModifierType.Additive;
            Debug.Assert(typePassed, "加算補正の種類", this);
            Check(typePassed, "加算補正の種類");

            bool valuePassed = modifier.Value == 2f;
            Debug.Assert(valuePassed, "加算補正の値", this);
            Check(valuePassed, "加算補正の値");

            var negative =
                ParameterModifier.CreateAdditive(-3f);

            bool negativePassed = negative.Value == -3f;
            Debug.Assert(negativePassed, "負数の加算補正", this);
            Check(negativePassed, "負数の加算補正");

            var zero =
                ParameterModifier.CreateAdditive(0f);

            bool zeroPassed = zero.Value == 0f;
            Debug.Assert(zeroPassed, "ゼロの加算補正", this);
            Check(zeroPassed, "ゼロの加算補正");

            var direct = new ParameterModifier(
                ParameterModifierType.Additive,
                5f);

            bool directPassed =
                direct.Type == ParameterModifierType.Additive &&
                direct.Value == 5f;
            Debug.Assert(directPassed, "加算補正の直接生成", this);
            Check(directPassed, "加算補正の直接生成");
        }

        /// <summary>
        /// 乗算補正の生成と保持情報を検証する。
        /// </summary>
        private void TestMultiplicative()
        {
            var modifier =
                ParameterModifier.CreateMultiplicative(1.5f);

            bool typePassed =
                modifier.Type ==
                ParameterModifierType.Multiplicative;
            Debug.Assert(typePassed, "乗算補正の種類", this);
            Check(typePassed, "乗算補正の種類");

            bool valuePassed = modifier.Value == 1.5f;
            Debug.Assert(valuePassed, "乗算補正の値", this);
            Check(valuePassed, "乗算補正の値");

            var reduction =
                ParameterModifier.CreateMultiplicative(0.5f);

            bool reductionPassed = reduction.Value == 0.5f;
            Debug.Assert(reductionPassed, "減少倍率の補正", this);
            Check(reductionPassed, "減少倍率の補正");

            var zero =
                ParameterModifier.CreateMultiplicative(0f);

            bool zeroPassed = zero.Value == 0f;
            Debug.Assert(zeroPassed, "ゼロ倍率の補正", this);
            Check(zeroPassed, "ゼロ倍率の補正");

            var direct = new ParameterModifier(
                ParameterModifierType.Multiplicative,
                2f);

            bool directPassed =
                direct.Type ==
                ParameterModifierType.Multiplicative &&
                direct.Value == 2f;
            Debug.Assert(directPassed, "乗算補正の直接生成", this);
            Check(directPassed, "乗算補正の直接生成");
        }

        /// <summary>
        /// 補正の識別子と個別識別を検証する。
        /// </summary>
        private void TestIdentifier()
        {
            var first =
                ParameterModifier.CreateAdditive(1f);

            var second =
                ParameterModifier.CreateAdditive(1f);

            bool emptyPassed = first.Id != Guid.Empty;
            Debug.Assert(emptyPassed, "有効な補正IDの生成", this);
            Check(emptyPassed, "有効な補正IDの生成");

            bool uniquePassed = first.Id != second.Id;
            Debug.Assert(uniquePassed, "補正IDの独立性", this);
            Check(uniquePassed, "補正IDの独立性");

            bool matchPassed = first.MatchesId(first.Id);
            Debug.Assert(matchPassed, "補正IDの一致判定", this);
            Check(matchPassed, "補正IDの一致判定");

            bool mismatchPassed = !first.MatchesId(second.Id);
            Debug.Assert(mismatchPassed, "補正IDの不一致判定", this);
            Check(mismatchPassed, "補正IDの不一致判定");
        }

        /// <summary>
        /// 補正元の保持と参照による識別を検証する。
        /// </summary>
        private void TestSource()
        {
            // 独立した補正元を生成する。
            object firstSource = new object();
            object secondSource = new object();

            var first =
                ParameterModifier.CreateAdditive(2f, firstSource);

            var second =
                ParameterModifier.CreateMultiplicative(
                    1.5f,
                    firstSource);

            var noSource =
                ParameterModifier.CreateAdditive(1f);

            bool referencePassed =
                ReferenceEquals(first.Source, firstSource);
            Debug.Assert(referencePassed, "補正元の保持", this);
            Check(referencePassed, "補正元の保持");

            bool matchPassed =
                first.IsFromSource(firstSource) &&
                second.IsFromSource(firstSource);
            Debug.Assert(matchPassed, "同一補正元の判定", this);
            Check(matchPassed, "同一補正元の判定");

            bool mismatchPassed =
                !first.IsFromSource(secondSource);
            Debug.Assert(mismatchPassed, "異なる補正元の判定", this);
            Check(mismatchPassed, "異なる補正元の判定");

            bool optionalPassed = noSource.Source == null;
            Debug.Assert(optionalPassed, "補正元の省略", this);
            Check(optionalPassed, "補正元の省略");

            bool nullPassed = !noSource.IsFromSource(null);
            Debug.Assert(nullPassed, "null補正元の除外", this);
            Check(nullPassed, "null補正元の除外");
        }

        /// <summary>
        /// 値に影響しない中立補正の判定を検証する。
        /// </summary>
        private void TestNeutral()
        {
            bool additiveZeroPassed =
                ParameterModifier.CreateAdditive(0f).IsNeutral;
            Debug.Assert(additiveZeroPassed, "加算0の中立判定", this);
            Check(additiveZeroPassed, "加算0の中立判定");

            bool additivePassed =
                !ParameterModifier.CreateAdditive(1f).IsNeutral;
            Debug.Assert(additivePassed, "加算1の非中立判定", this);
            Check(additivePassed, "加算1の非中立判定");

            bool multiplierOnePassed =
                ParameterModifier
                    .CreateMultiplicative(1f).IsNeutral;
            Debug.Assert(multiplierOnePassed, "倍率1の中立判定", this);
            Check(multiplierOnePassed, "倍率1の中立判定");

            bool multiplierZeroPassed =
                !ParameterModifier
                    .CreateMultiplicative(0f).IsNeutral;
            Debug.Assert(multiplierZeroPassed, "倍率0の非中立判定", this);
            Check(multiplierZeroPassed, "倍率0の非中立判定");

            bool multiplierPassed =
                !ParameterModifier
                    .CreateMultiplicative(1.5f).IsNeutral;
            Debug.Assert(multiplierPassed, "倍率1.5の非中立判定", this);
            Check(multiplierPassed, "倍率1.5の非中立判定");
        }

        /// <summary>
        /// 不正な補正値と補正方法の拒否を検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            bool typePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new ParameterModifier(
                        (ParameterModifierType)999,
                        1f);
                });
            Debug.Assert(typePassed, "未対応補正方法の拒否", this);
            Check(typePassed, "未対応補正方法の拒否");

            bool nanPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    ParameterModifier.CreateAdditive(float.NaN);
                });
            Debug.Assert(nanPassed, "NaN加算値の拒否", this);
            Check(nanPassed, "NaN加算値の拒否");

            bool positiveInfinityPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    ParameterModifier.CreateAdditive(
                        float.PositiveInfinity);
                });
            Debug.Assert(
                positiveInfinityPassed,
                "正の無限大の拒否",
                this);
            Check(positiveInfinityPassed, "正の無限大の拒否");

            bool negativeInfinityPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    ParameterModifier.CreateAdditive(
                        float.NegativeInfinity);
                });
            Debug.Assert(
                negativeInfinityPassed,
                "負の無限大の拒否",
                this);
            Check(negativeInfinityPassed, "負の無限大の拒否");

            bool negativeMultiplierPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    ParameterModifier.CreateMultiplicative(-1f);
                });
            Debug.Assert(
                negativeMultiplierPassed,
                "負数倍率の拒否",
                this);
            Check(negativeMultiplierPassed, "負数倍率の拒否");

            bool nanMultiplierPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    ParameterModifier.CreateMultiplicative(float.NaN);
                });
            Debug.Assert(
                nanMultiplierPassed,
                "NaN倍率の拒否",
                this);
            Check(nanMultiplierPassed, "NaN倍率の拒否");
        }

        /// <summary>
        /// 確認用文字列に必要な情報が含まれることを検証する。
        /// </summary>
        private void TestToString()
        {
            var modifier =
                ParameterModifier.CreateAdditive(2f);

            string result = modifier.ToString();

            bool typePassed =
                result.Contains(
                    ParameterModifierType.Additive.ToString());
            Debug.Assert(typePassed, "文字列への補正方法の反映", this);
            Check(typePassed, "文字列への補正方法の反映");

            bool idPassed =
                result.Contains(modifier.Id.ToString());
            Debug.Assert(idPassed, "文字列への補正IDの反映", this);
            Check(idPassed, "文字列への補正IDの反映");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                // 期待する例外型との完全一致を確認する。
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                // 成功件数を加算し、個別ログを出力する。
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                // 失敗件数を加算し、エラーログを出力する。
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
